/* ============================================================
   AnotherLife — the job market

   Every job: { id, sector, name, tier, base, ladder[4], gradType? }
     tier 0  no qualifications      base  18k–40k
     tier 1  high school diploma    base  30k–78k
     tier 2  bachelor's degree      base  48k–135k
     tier 3  postgraduate           base  95k–300k  (needs a matching gradType)

   `sector` exists because the listings screen groups by it — a school leaver
   qualifies for a couple of hundred of these and a flat list is unreadable.

   Ranked professions get their real ladders (police, fire, ambulance,
   military, medicine, law, sea and air). Everything else uses the two
   patterns below, which is honest: most jobs really are junior/senior/lead.
   ============================================================ */

const step = t => [`Junior ${t}`, t, `Senior ${t}`, `Lead ${t}`];
const grow = t => [`Trainee ${t}`, t, `Senior ${t}`, `Head of ${t}`];
const J = (sector, id, name, tier, base, ladder, gradType) =>
  gradType ? { id, sector, name, tier, base, ladder, gradType }
           : { id, sector, name, tier, base, ladder };

